import{_ as l,c as i,o as e,ag as r}from"./chunks/framework.B1jFR3yW.js";const c=JSON.parse('{"title":"001 机器学习概述","description":"","frontmatter":{},"headers":[],"relativePath":"python/机器学习/001机器学习概述.md","filePath":"python/机器学习/001机器学习概述.md"}'),t={name:"python/机器学习/001机器学习概述.md"};function h(o,a,n,s,d,u){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="_001-机器学习概述" tabindex="-1">001 机器学习概述 <a class="header-anchor" href="#_001-机器学习概述" aria-label="Permalink to &quot;001 机器学习概述&quot;">​</a></h1><h2 id="什么是机器学习" tabindex="-1">什么是机器学习 <a class="header-anchor" href="#什么是机器学习" aria-label="Permalink to &quot;什么是机器学习&quot;">​</a></h2><p>机器学习不是一堆算法名词，而是一套从数据中学习规律，再用规律处理新数据的方法。</p><p>和传统规则编程相比：</p><ul><li>规则编程：程序员先写规则，机器再执行</li><li>机器学习：先给数据，算法自动总结规律，再进行预测</li></ul><h2 id="ai、机器学习、深度学习的关系" tabindex="-1">AI、机器学习、深度学习的关系 <a class="header-anchor" href="#ai、机器学习、深度学习的关系" aria-label="Permalink to &quot;AI、机器学习、深度学习的关系&quot;">​</a></h2><ul><li>AI：人工智能</li><li>ML：机器学习，是实现 AI 的一种方法</li><li>DL：深度学习，是机器学习中的一类方法</li></ul><p>可以简单理解为：</p><p><code>人工智能 &gt; 机器学习 &gt; 深度学习</code></p><h2 id="机器学习的应用场景" tabindex="-1">机器学习的应用场景 <a class="header-anchor" href="#机器学习的应用场景" aria-label="Permalink to &quot;机器学习的应用场景&quot;">​</a></h2><p>常见应用包括：</p><ul><li>图像识别</li><li>语音识别</li><li>搜索排序</li><li>推荐系统</li><li>风险控制</li><li>用户分析</li><li>销量预测</li><li>文本分类</li></ul><h2 id="机器学习发展三要素" tabindex="-1">机器学习发展三要素 <a class="header-anchor" href="#机器学习发展三要素" aria-label="Permalink to &quot;机器学习发展三要素&quot;">​</a></h2><ul><li>数据</li><li>算法</li><li>算力</li></ul><p>实际工作里，数据质量往往比模型名字更重要。</p><h2 id="常见术语" tabindex="-1">常见术语 <a class="header-anchor" href="#常见术语" aria-label="Permalink to &quot;常见术语&quot;">​</a></h2><h3 id="样本" tabindex="-1">样本 <a class="header-anchor" href="#样本" aria-label="Permalink to &quot;样本&quot;">​</a></h3><p>一条数据就是一个样本。</p><h3 id="特征" tabindex="-1">特征 <a class="header-anchor" href="#特征" aria-label="Permalink to &quot;特征&quot;">​</a></h3><p>对结果预测有帮助的字段就是特征。</p><h3 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to &quot;标签&quot;">​</a></h3><p>模型最终要预测的那一列数据就是标签，也叫目标值。</p><h2 id="分类、回归、聚类" tabindex="-1">分类、回归、聚类 <a class="header-anchor" href="#分类、回归、聚类" aria-label="Permalink to &quot;分类、回归、聚类&quot;">​</a></h2><h3 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h3><p>预测离散类别。</p><p>例如：</p><ul><li>是否流失</li><li>是猫还是狗</li><li>是垃圾邮件还是正常邮件</li></ul><h3 id="回归" tabindex="-1">回归 <a class="header-anchor" href="#回归" aria-label="Permalink to &quot;回归&quot;">​</a></h3><p>预测连续数值。</p><p>例如：</p><ul><li>房价</li><li>销量</li><li>温度</li></ul><h3 id="聚类" tabindex="-1">聚类 <a class="header-anchor" href="#聚类" aria-label="Permalink to &quot;聚类&quot;">​</a></h3><p>训练数据没有标签，目标是自动把相似样本分到一组。</p><h2 id="有监督与无监督学习" tabindex="-1">有监督与无监督学习 <a class="header-anchor" href="#有监督与无监督学习" aria-label="Permalink to &quot;有监督与无监督学习&quot;">​</a></h2><h3 id="有监督学习" tabindex="-1">有监督学习 <a class="header-anchor" href="#有监督学习" aria-label="Permalink to &quot;有监督学习&quot;">​</a></h3><p>训练数据有标签，典型任务是分类和回归。</p><h3 id="无监督学习" tabindex="-1">无监督学习 <a class="header-anchor" href="#无监督学习" aria-label="Permalink to &quot;无监督学习&quot;">​</a></h3><p>训练数据没有标签，典型任务是聚类和降维。</p><h2 id="训练集和测试集" tabindex="-1">训练集和测试集 <a class="header-anchor" href="#训练集和测试集" aria-label="Permalink to &quot;训练集和测试集&quot;">​</a></h2><p>常见划分方式：</p><ul><li><code>8:2</code></li><li><code>7:3</code></li></ul><p>含义：</p><ul><li>训练集：让模型学习规律</li><li>测试集：检查模型在新数据上的表现</li></ul><h2 id="建模流程" tabindex="-1">建模流程 <a class="header-anchor" href="#建模流程" aria-label="Permalink to &quot;建模流程&quot;">​</a></h2><p>一条最常见的机器学习流程：</p><ol><li>明确问题</li><li>收集和理解数据</li><li>做特征工程</li><li>选择算法</li><li>训练模型</li><li>评估模型</li><li>调参与优化</li><li>落地应用</li></ol><h2 id="特征工程" tabindex="-1">特征工程 <a class="header-anchor" href="#特征工程" aria-label="Permalink to &quot;特征工程&quot;">​</a></h2><p>特征工程决定模型上限，常见工作包括：</p><ul><li>特征提取</li><li>特征预处理</li><li>特征选择</li><li>特征降维</li><li>特征组合</li></ul><h2 id="欠拟合、过拟合、泛化" tabindex="-1">欠拟合、过拟合、泛化 <a class="header-anchor" href="#欠拟合、过拟合、泛化" aria-label="Permalink to &quot;欠拟合、过拟合、泛化&quot;">​</a></h2><h3 id="欠拟合" tabindex="-1">欠拟合 <a class="header-anchor" href="#欠拟合" aria-label="Permalink to &quot;欠拟合&quot;">​</a></h3><ul><li>训练集表现差</li><li>测试集表现也差</li></ul><p>通常说明模型太简单。</p><h3 id="过拟合" tabindex="-1">过拟合 <a class="header-anchor" href="#过拟合" aria-label="Permalink to &quot;过拟合&quot;">​</a></h3><ul><li>训练集表现很好</li><li>测试集表现差</li></ul><p>通常说明模型把训练数据里的噪声也学进去了。</p><h3 id="泛化" tabindex="-1">泛化 <a class="header-anchor" href="#泛化" aria-label="Permalink to &quot;泛化&quot;">​</a></h3><p>泛化能力就是模型面对新数据时是否还有效。</p><h2 id="sklearn-环境" tabindex="-1">sklearn 环境 <a class="header-anchor" href="#sklearn-环境" aria-label="Permalink to &quot;sklearn 环境&quot;">​</a></h2><p>这套传统机器学习内容大多可以基于 <code>scikit-learn</code> 学习：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scikit-learn</span></span></code></pre></div><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>这一篇最重要的不是背定义，而是先建立全局框架：</p><ul><li>知道机器学习解决什么问题</li><li>知道分类、回归、聚类的区别</li><li>知道训练集和测试集的作用</li><li>知道特征工程和泛化为什么重要</li></ul>',64)])])}const b=l(t,[["render",h]]);export{c as __pageData,b as default};
